/* Midnight is real local midnight; completed work carries the elves' good fortune. */
(()=>{'use strict';
function ensure(s){if(!s.cityFortune||typeof s.cityFortune!=='object'||Array.isArray(s.cityFortune))s.cityFortune={};const f=s.cityFortune;for(const k of ['seen','waiting'])if(!f[k]||typeof f[k]!=='object'||Array.isArray(f[k]))f[k]={};for(const k of ['made','earned','gift','nights'])if(!Number.isSafeInteger(f[k])||f[k]<0)f[k]=0;if(!Array.isArray(f.ledger))f.ledger=[];return f}
function counters(s){const jobs=s.cityLife?.jobs||{},h=s.cityHeritage||{};return{boots:s.crafted||0,academy:s.academy||0,harvest:s.gardensTended||0,cobbler:jobs.cobbler||0,baker:jobs.baker||0,healer:jobs.healer||0,gardener:jobs.gardener||0,home:Object.values(s.cityLife?.upgrades||{}).filter(Boolean).length,heritage:Object.values(h.completed||{}).filter(Boolean).length}}
const titles={boots:'Handmade boots',academy:'Moonlight craft',harvest:'Grown with care',cobbler:'Shoemaker’s work',baker:'Freshly baked work',healer:'Apothecary’s work',gardener:'Garden craft',home:'A home project',heritage:'A tale carried forward'};
function log(f,text){f.ledger.unshift(text);f.ledger=f.ledger.slice(0,30)}
function dawn(c){return c.ordinal-(c.hour<6?1:0)}
function observe(s,c){const f=ensure(s),now=counters(s);if(!f.initialized){f.seen=now;f.initialized=true;f.lastDawn=dawn(c);return{made:0,coins:0}}let made=0;for(const [key,n]of Object.entries(now)){const previous=f.seen[key]||0;f.seen[key]=n;if(n>previous){const count=n-previous;made+=count;log(f,titles[key]+' · '+count+' elven-finished · +'+count*5+' fortune')}}if(made){f.made+=made;f.earned+=made*5;s.coins+=made*5;const due=String(c.ordinal+(c.hour<6?0:1));f.waiting[due]=(f.waiting[due]||0)+made}return{made,coins:made*5}}
function roll(s,c){const f=ensure(s),d=dawn(c);if(!Number.isSafeInteger(f.lastDawn)){f.lastDawn=d;return false}if(d<=f.lastDawn)return false;let work=0;for(const [key,count]of Object.entries(f.waiting)){if(Number(key)<=d){work+=count;delete f.waiting[key]}}f.lastDawn=d;f.nights++;const gift=12+work*2;f.gift+=gift;log(f,'The midnight helpers finished a pair · '+gift+' mooncoins waiting at the original shop'+(work?' · '+work+' creations blessed overnight':''));return true}
function claim(s,w){const f=ensure(s);if(w?.district!=='workshop'||w?.room!=='originalShop'||w.porch||f.gift<=0)return{ok:false,reason:'Visit the original shoemaker’s shop when the morning gift is ready.'};const coins=f.gift;f.gift=0;f.earned+=coins;s.coins+=coins;log(f,'Collected the helpers’ morning fortune · +'+coins+' mooncoins');return{ok:true,coins}}
globalThis.EldoriaFortuneModel={ensure,counters,observe,roll,claim,dawn};
})();
